entries[32720] = { ["name"] = "Zeitverlorene Opfergabe", ["text"] = "\"Dient der Beschwörung von Terokk beim uralten Schädelhaufen auf Terroks Ruh.\"" }
entries[32721] = { ["name"] = "Rationen der Himmelswache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Stellt im Verlauf von 30 Sek. ( 284 * 30 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 3 Ausdauer und 3 Vielseitigkeit.\nBenötigt Himmelswache der Sha'tari\n- Wohlwollend\nVerkaufspreis:" }
entries[32722] = { ["name"] = "Angereicherter Terozapfensaft", ["text"] = "Einzigartig (20)\nBenutzen: Stellt im Verlauf von 30 Sek. 1180 Gesundheit und ( 840 / 5 * 30) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\nBenötigt Himmelswache der Sha'tari\n- Freundlich\nVerkaufspreis:" }
entries[32723] = { ["name"] = "Fracht der Netherminen", ["text"] = "Questgegenstand" }
entries[32724] = { ["name"] = "Schlickbedecktes Objekt", ["text"] = "Wird beim Aufheben gebunden\n\"Welch wundersame Schätze mögen wohl unter dem Schlick verborgen sein?\"\n<Zum Öffnen rechtsklicken>" }
entries[32725] = { ["name"] = "Spitzhacke der Finsterblut", ["text"] = "\"Diese Hacke hat schon bessere Zeiten gesehen.\"\nVerkaufspreis:" }
entries[32726] = { ["name"] = "Fluchtpläne der Finsterblut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Netherschwingen\n- Freundlich\n\"Ein ausführliches Schriftstück, das einen von den Minenarbeitern der Finsterblut geplanten Aufstand beschreibt.\"" }
