entries[32732] = { ["name"] = "Drachenzähne", ["text"] = "Questgegenstand\nEinzigartig\n\"Sie sind rasiermesserscharf und sehen auch ohne Drachenmal noch tödlich aus.\"" }
entries[32733] = { ["name"] = "Teufelspeitsche", ["text"] = "Questgegenstand\nEinzigartig\n\"Mit Obsidiansplittern besetzt. Fragt gar nicht erst, aus welchem Leder sie gefertigt wurde.\"" }
