entries[32752] = { ["name"] = "Muster: Flinkheiltücher", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung von Flinkheiltüchern.\nBenötigt Schneiderei der Scherbenwelt (75)\nVerkaufspreis:\nFlinkheiltücher\nWird beim Anlegen gebunden\nHandgelenk Stoff\n2 Rüstung\n+2 Intelligenz\n+3 Ausdauer\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 55 / 55\nVerkaufspreis:\nBenötigt Magieerfüllter Netherstoffballen (3), Urmondstoff (4), Urleben (8), Herz der Dunkelheit (4)" }
entries[32753] = { ["name"] = "Muster: Flinkheilmantelung", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer Flinkheilmantelung.\nBenötigt Schneiderei der Scherbenwelt (75)\nVerkaufspreis:\nFlinkheilmantelung\nWird beim Aufheben gebunden\nSchulter Stoff\n3 Rüstung\n+3 Intelligenz\n+2 Ausdauer\nErhöht Eure Tempowertung um + 3.\n+ 3 Vielseitigkeit\nHaltbarkeit 100 / 100\nVerkaufspreis:\nBenötigt Magieerfüllter Netherstoffballen (4), Urmondstoff (2), Urleben (6), Herz der Dunkelheit (2)" }
entries[32754] = { ["name"] = "Muster: Armschienen des flinken Gedankens", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung von Armschienen des flinken Gedankens.\nBenötigt Schneiderei der Scherbenwelt (75)\nVerkaufspreis:\nArmschienen des flinken Gedankens\nWird beim Anlegen gebunden\nHandgelenk Stoff\n2 Rüstung\n+2 Intelligenz\n+3 Ausdauer\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 55 / 55\nVerkaufspreis:\nBenötigt Magieerfüllter Netherstoffballen (3), Zauberstoff (4), Urmana (8), Herz der Dunkelheit (4)" }
entries[32755] = { ["name"] = "Muster: Mantelung des flinken Gedankens", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer Mantelung des flinken Gedankens.\nBenötigt Schneiderei der Scherbenwelt (75)\nVerkaufspreis:\nMantelung des flinken Gedankens\nWird beim Aufheben gebunden\nSchulter Stoff\n3 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 100 / 100\nVerkaufspreis:\nBenötigt Magieerfüllter Netherstoffballen (4), Zauberstoff (2), Urmana (6), Herz der Dunkelheit (2)" }
entries[32756] = { ["name"] = "Gyrobalancierter Khoriumzerstörer", ["text"] = "Wird beim Anlegen gebunden\nDistanz Schusswaffe\n5 - 11 Schaden Geschwindigkeit 3.00\n(2.7 Schaden pro Sekunde)\n+4 Beweglichkeit\n+9 Ausdauer\n\nPrismatischer Sockel\nSockelbonus: + 1 Ausdauer\n\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[32757] = { ["name"] = "Gesegnetes Medaillon von Karabor", ["text"] = "Wird beim Aufheben gebunden\nHals\n+4 Ausdauer\n+2 Schattenwiderstand\nBenutzen: Teleportiert den Träger an die Stufen von Illidans Festung. (15 Min Abklingzeit)\n\"Dieser Gegenstand, einst von einem Kleriker von Karabor getragen, gewährt dem Träger Einlass in den Schwarzen Tempel.\"" }
entries[32758] = { ["name"] = "Eau de Schläger", ["text"] = "Benutzen: Schüttet es über Euren gesamten Körper, um wie ein kultivierter Oger zu riechen. Sämtliche Wesen werden Euch sicherlich schon von weitem bemerken.\n\nNur im Schergrat anwendbar.\n\"Ein erlesener Duft für den anspruchsvollen Oger.\"\nVerkaufspreis:" }
entries[32759] = { ["name"] = "Beschleunigermodul", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Wird benutzt, um die Steuerungen für Protonenbeschleunigung am Landeplatz von Bash'ir zu aktivieren.\"\nVerkaufspreis:" }
entries[32760] = { ["name"] = "Pfeil des Machognoms", ["text"] = "Wird beim Aufheben gebunden\nMunition\n\"Befiedert von Andy 'Der Machognom' Savage.\"\nVerkaufspreis:" }
entries[32761] = { ["name"] = "Die Offizierskugel", ["text"] = "Wird beim Aufheben gebunden\nMunition\n\"Mächtiges Badabumm.\"\nVerkaufspreis:" }
entries[32762] = { ["name"] = "Rulksters Hirnsaft", ["text"] = "Benutzen: Stellt 682 Mana wieder her. (5 Min Abklingzeit)\n\"Sei kein Dummkopf, trink deinen Hirnsaft!\"\nVerkaufspreis:" }
entries[32763] = { ["name"] = "Rulksters Geheimsoße", ["text"] = "Benutzen: Stellt 750 Gesundheit wieder her. (5 Min Abklingzeit)\n\"Trinkt und lebt.\"\nVerkaufspreis:" }
entries[32764] = { ["name"] = "Flaschataurens himmlisches Gebräu", ["text"] = "Benutzen: Erhöht 1 Stunde lang Euer Ausweichen um 1 und Eure Maximalgesundheit um 29 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Der Effekt hält auch nach dem Tode an. (3 Sek. Abklingzeit)\n\"Die flaschenhafte Essenz des mythenumrankten Wesens!\"\nVerkaufspreis:" }
entries[32765] = { ["name"] = "Flaschataurens Tränen", ["text"] = "Benutzen: Erhöht die Angriffskraft 1 Stunde lang um 16 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\n\"Die destillierten Tränen des schwer zu fassenden Flaschatauren.\"\nVerkaufspreis:" }
entries[32766] = { ["name"] = "Flaschataurens Fläschchen der Flaschität", ["text"] = "Benutzen: Erhöht Eure Vielseitigkeit 1 Stunde lang um 16 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\n\"Trägt das Zeichen des Flaschatauren.\"\nVerkaufspreis:" }
entries[32767] = { ["name"] = "Flaschataurens Fläschchen der ziemlich beeindruckenden Macht", ["text"] = "Benutzen: Erhöht die Zaubermacht 1 Stunde lang um 29 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\n\"Nicht überragend, aber auch nicht so schlecht.\"\nVerkaufspreis:" }
entries[32768] = { ["name"] = "Zügel des Rabenfürsten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein riesiges Rabenreittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der Rest soll vergessen bleiben auf der Erde, mit gestutzten Flügeln und in Schande. - Wort des Raben\"\nBeute von:\nAnzu\nZone:\nSethekkhallen (Heroisch)" }
