entries[33164] = { ["name"] = "Immerbrandfackeln", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Schleudert eine Immerbrandfackel bis zu 20 Meter weit und zündet damit einen Pestkessel an. Kann nur in Halgrind verwendet werden.\n\"Wie kommt es, dass die Dinger nicht aufhören, zu brennen? Es kann nur Magie sein!\"" }
entries[33165] = { ["name"] = "Formel: Waffe - Große Beweglichkeit", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Große Beweglichkeit' bei einer Waffe durchführt.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass die Beweglichkeit um 8 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst der Scherbenwelt (50)\nBenötigt Das Violette Auge\n- Ehrfürchtig\nVerkaufspreis:" }
entries[33166] = { ["name"] = "Pagles Fischpaste, extra stark", ["text"] = "Questgegenstand\nBenutzen: Schmiert Euch vollständig mit der Paste ein und bereitet Euch auf die Begegnung mit einigen Meereswesen vor. (5 Min Abklingzeit)\n\"Ein Glas mit der ranzigsten, aus Fischabfällen hergestellten Paste, die Ihr je gesehen habt.\"" }
