entries[33224] = { ["name"] = "Zügel des Spektraltigers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Spektraltiger und gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wie es sich für einen Goblin gehört, hat Landro Fernblick den Vertrieb dieser geheimnisvollen körperlosen Reittiere fest im Klammergriff.\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht" }
